import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

export default function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('');
  const [selectedY, setSelectedY] = useState('');
  const [chartType, setChartType] = useState('ScatterChart');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    axios.get('http://localhost:8000/data/columns')
      .then(res => {
        setColumns(res.data.columns);
        if (res.data.columns.length > 1) {
          setSelectedX(res.data.columns[0]);
          setSelectedY(res.data.columns[1]);
        }
      });
  }, []);

  useEffect(() => {
    if (selectedX && selectedY) {
      setLoading(true);
      axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY }
      })
      .then(res => {
        const chartData = [
          [selectedX, selectedY],
          ...res.data.map(item => [item[selectedX], item[selectedY]])
        ];
        setData(chartData);
      })
      .finally(() => setLoading(false));
    }
  }, [selectedX, selectedY]);

  return (
    <div className="visualization">
      <h2>Data Visualization</h2>
      
      <div className="controls">
        <div>
          <label>X-Axis:</label>
          <select value={selectedX} onChange={e => setSelectedX(e.target.value)}>
            {columns.map(col => <option key={col} value={col}>{col}</option>)}
          </select>
        </div>
        
        <div>
          <label>Y-Axis:</label>
          <select value={selectedY} onChange={e => setSelectedY(e.target.value)}>
            {columns.map(col => <option key={col} value={col}>{col}</option>)}
          </select>
        </div>
        
        <div>
          <label>Chart Type:</label>
          <select value={chartType} onChange={e => setChartType(e.target.value)}>
            <option value="ScatterChart">Scatter</option>
            <option value="LineChart">Line</option>
            <option value="BarChart">Bar</option>
          </select>
        </div>
      </div>

      {loading ? (
        <p>Loading chart...</p>
      ) : data.length > 0 ? (
        <Chart
          chartType={chartType}
          width="100%"
          height="400px"
          data={data}
          options={{
            title: `${selectedY} vs ${selectedX}`,
            hAxis: { title: selectedX },
            vAxis: { title: selectedY },
          }}
        />
      ) : (
        <p>Select parameters to visualize</p>
      )}
    </div>
  );
}
